template<typename Key, typename Value>
class LRUCache {
private:
    // Node structure for doubly linked list
    struct Node {
        Key key;
        Value value;
        Node* prev;
        Node* next;

        Node(const Key& k, const Value& v) : key(k), value(v), prev(nullptr), next(nullptr) {}
    };

    // Capacity of the cache
    size_t capacity_;

    // Doubly linked list pointers
    Node* head_; // Most recently used
    Node* tail_; // Least recently used

    // Hash map for O(1) access
    std::unordered_map<Key, Node*> cache_;

    // Mutex for thread safety
    mutable std::shared_mutex mutex_;

    // Remove a node from the linked list
    void removeNode(Node* node) {
        if (node->prev) {
            node->prev->next = node->next;
        } else {
            head_ = node->next;
        }

        if (node->next) {
            node->next->prev = node->prev;
        } else {
            tail_ = node->prev;
        }
    }

    // Add a node to the front (most recently used position)
    void addToFront(Node* node) {
        node->next = head_;
        node->prev = nullptr;

        if (head_) {
            head_->prev = node;
        }
        head_ = node;

        if (!tail_) {
            tail_ = head_;
        }
    }

    // Move an existing node to the front
    void moveToFront(Node* node) {
        removeNode(node);
        addToFront(node);
    }

    // Evict the least recently used node
    void evictLRU() {
        if (tail_) {
            Node* lruNode = tail_;

            // Remove from hash map
            cache_.erase(lruNode->key);

            // Remove from linked list
            removeNode(lruNode);

            // Delete the node
            delete lruNode;
        }
