class Resource {
public:
    Resource() { std::cout << "Resource acquired\n"; }
    ~Resource() { std::cout << "Resource released\n"; }
    void doWork() { std::cout << "Working...\n"; }
};

class Container {
    Resource* res1;
    Resource* res2;
public:
    Container() : res1(new Resource()), res2(new Resource()) {}

    ~Container() {
        delete res1;
        delete res2;
    }

    void process() {
        res1->doWork();
        res2->doWork();
    }
};

